import { execSync } from 'node:child_process'
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { fileURLToPath, URL } from 'node:url'

import { defineConfig, type DefaultTheme, type HeadConfig, type LocaleConfig } from 'vitepress'

// Generated by `scripts/generate-docs.mjs` — one VitePress sidebar *group* per
// component category (the same grouping shopify.dev uses), each holding the
// component reference pages under `docs/components/`. The codegen script owns
// this file wholesale, so nothing here needs touching beyond re-running
// `npm run docs:generate`.
import componentsSidebar from './components-sidebar.json'
import type viTheme from '../locales/vi/theme.json'

// Public origin of the deployed docs. Used for canonical URLs, Open Graph tags,
// JSON-LD and the generated sitemap — keep it in sync with the Cloudflare route.
const SITE_URL = 'https://polaris-vue-elements.dev'
const SITE_NAME = 'polaris-vue-elements'
const SITE_DESCRIPTION =
  'Typed Vue 3 wrapper components for Shopify Polaris web components — props, events and v-model generated from the official Custom Elements Manifest.'
const OG_IMAGE = `${SITE_URL}/og.png`

// Every language has docs/locales/<code>/theme.json (labels, UI strings); English
// is the root locale. Translated pages live under docs/<code>/ and mirror the
// English page tree, so a page's counterpart in another language is the same
// path with the prefix added or removed.
type Theme = typeof viTheme
type Locale = Theme & { code: string; prefix: string }

const localesDir = fileURLToPath(new URL('../locales', import.meta.url))
const LOCALES: Locale[] = readdirSync(localesDir)
  .filter((code) => existsSync(`${localesDir}/${code}/theme.json`))
  .map((code) =>
    Object.assign(JSON.parse(readFileSync(`${localesDir}/${code}/theme.json`, 'utf8')) as Theme, {
      code,
      prefix: code === 'en' ? '' : `${code}/`,
    }),
  )
  .toSorted((a, b) => (a.code === 'en' ? -1 : b.code === 'en' ? 1 : a.code.localeCompare(b.code)))

function localeOf(relativePath: string): Locale {
  return LOCALES.find((l) => l.prefix !== '' && relativePath.startsWith(l.prefix)) ?? LOCALES[0]
}

function counterpart(relativePath: string, target: Locale): string {
  const own = localeOf(relativePath)
  return target.prefix + relativePath.slice(own.prefix.length)
}

// `relativePath` is the source file (`components/s-button.md`, `index.md`);
// with `cleanUrls` the public URL drops both `.md` and any trailing `index`.
function pageUrl(relativePath: string): string {
  const pathname = relativePath.replace(/(^|\/)index\.md$/, '$1').replace(/\.md$/, '')
  return `${SITE_URL}/${pathname}`
}

// Cloudflare Workers Builds checks out a shallow clone, where every file's last
// commit is the tip — so `lastUpdated` would stamp all pages (and every sitemap
// `<lastmod>`) with the same date, and Google learns to ignore lastmod. Fetch the
// full history when we can; if that fails, omit the dates rather than publish
// wrong ones.
function isShallowClone(): boolean {
  return execSync('git rev-parse --is-shallow-repository', { encoding: 'utf8' }).trim() === 'true'
}

function hasFullGitHistory(): boolean {
  try {
    if (isShallowClone()) execSync('git fetch --unshallow --quiet', { stdio: 'ignore' })
    return !isShallowClone()
  } catch {
    return false
  }
}

function guideSidebar(l: Locale, prefix: string): DefaultTheme.SidebarItem {
  return {
    text: l.sidebarGuide.title,
    items: [
      { text: l.sidebarGuide.gettingStarted, link: `${prefix}/guide/getting-started` },
      { text: l.sidebarGuide.embeddedApp, link: `${prefix}/guide/shopify-embedded-app` },
      { text: l.sidebarGuide.quirks, link: `${prefix}/guide/quirks` },
      { text: l.sidebarGuide.allComponents, link: `${prefix}/components/` },
    ],
  }
}

// English is configured at the top level (root locale); every other language
// gets its own nav, sidebar and UI labels from its theme.json.
function localeConfigs(): LocaleConfig<DefaultTheme.Config> {
  const configs: LocaleConfig<DefaultTheme.Config> = { root: { label: LOCALES[0].label, lang: LOCALES[0].lang } }
  for (const l of LOCALES.slice(1)) {
    const prefix = `/${l.code}`
    const sidebar = JSON.parse(
      readFileSync(fileURLToPath(new URL(`./components-sidebar.${l.code}.json`, import.meta.url)), 'utf8'),
    ) as DefaultTheme.SidebarItem[]
    configs[l.code] = {
      label: l.label,
      lang: l.lang,
      link: `${prefix}/`,
      description: l.siteDescription,
      themeConfig: {
        nav: [
          { text: l.nav.guide, link: `${prefix}/guide/getting-started` },
          { text: l.nav.components, link: `${prefix}/components/` },
        ],
        sidebar: [guideSidebar(l, prefix), ...sidebar],
        outline: { level: [2, 3], label: l.ui.outlineLabel },
        docFooter: { prev: l.ui.prev, next: l.ui.next },
        lastUpdated: { text: l.ui.lastUpdated },
        darkModeSwitchLabel: l.ui.darkModeSwitchLabel,
        lightModeSwitchTitle: l.ui.lightModeSwitchTitle,
        darkModeSwitchTitle: l.ui.darkModeSwitchTitle,
        sidebarMenuLabel: l.ui.sidebarMenuLabel,
        returnToTopLabel: l.ui.returnToTopLabel,
        langMenuLabel: l.ui.langMenuLabel,
        notFound: { title: l.ui.notFoundTitle, quote: l.ui.notFoundQuote, linkText: l.ui.notFoundLink },
        footer: l.footer,
      },
    }
  }
  return configs
}

function searchLocales() {
  return Object.fromEntries(
    LOCALES.slice(1).map((l) => [
      l.code,
      {
        translations: {
          button: { buttonText: l.search.buttonText, buttonAriaLabel: l.search.buttonText },
          modal: {
            displayDetails: l.search.displayDetails,
            resetButtonTitle: l.search.resetButtonTitle,
            backButtonTitle: l.search.backButtonTitle,
            noResultsText: l.search.noResultsText,
            footer: {
              selectText: l.search.selectText,
              navigateText: l.search.navigateText,
              closeText: l.search.closeText,
            },
          },
        },
      },
    ]),
  )
}

// https://vitepress.dev/reference/site-config
export default defineConfig({
  lang: 'en-US',
  title: SITE_NAME,
  description: SITE_DESCRIPTION,

  // Cloudflare Workers static assets 307-redirects `/foo.html` → `/foo`, so
  // emitting `.html` links would send every crawler hop through a redirect.
  // Clean URLs make the links VitePress writes match what Cloudflare serves.
  cleanUrls: true,

  // Git-based "last updated" per page; also feeds `<lastmod>` in the sitemap.
  lastUpdated: hasFullGitHistory(),

  // Emits /sitemap.xml at build time from every routed page, with hreflang
  // alternates linking each page to its translations.
  sitemap: {
    hostname: SITE_URL,
    transformItems(items) {
      const urls = new Set(items.map((item) => item.url))
      return items.map((item) => {
        const path = item.url === '' ? 'index.md' : `${item.url.replace(/\/$/, '/index')}.md`
        const links = LOCALES.map((l) => {
          const url = counterpart(path, l).replace(/(^|\/)index\.md$/, '$1').replace(/\.md$/, '')
          return { lang: l.hreflang, url: `${SITE_URL}/${url}`, exists: urls.has(url) }
        }).filter((l) => l.exists)
        return links.length > 1 ? { ...item, links: links.map(({ lang, url }) => ({ lang, url })) } : item
      })
    },
  },

  // `docs/examples/*.md` and `docs/best-practices/*.md` are hand-written
  // snippets that `generate-docs.mjs` inlines into the component pages. Examples
  // must live under `docs/` so the demos can import from `./demos/`, but neither
  // are pages — building them would publish duplicate-content URLs.
  srcExclude: ['examples/**', 'best-practices/**', 'locales/**'],

  head: [
    // Google Search wants a square icon at a multiple of 48px; browsers prefer the SVG.
    ['link', { rel: 'icon', href: '/favicon.svg', type: 'image/svg+xml' }],
    ['link', { rel: 'icon', href: '/favicon-96x96.png', type: 'image/png', sizes: '96x96' }],
    ['link', { rel: 'icon', href: '/favicon-48x48.png', type: 'image/png', sizes: '48x48' }],
    ['link', { rel: 'icon', href: '/favicon.ico', sizes: '32x32' }],
    ['link', { rel: 'apple-touch-icon', href: '/apple-touch-icon.png' }],
    ['meta', { name: 'theme-color', content: '#008060' }],
    ['meta', { property: 'og:site_name', content: SITE_NAME }],
    ['meta', { property: 'og:type', content: 'website' }],
    ['meta', { property: 'og:image', content: OG_IMAGE }],
    ['meta', { property: 'og:image:width', content: '1200' }],
    ['meta', { property: 'og:image:height', content: '630' }],
    ['meta', { name: 'twitter:card', content: 'summary_large_image' }],
    ['meta', { name: 'twitter:image', content: OG_IMAGE }],
    // Loads the real Polaris custom element definitions so that live examples
    // in the docs (and the components used to render this site itself) work
    // exactly as they would in a consuming app.
    ['script', { src: 'https://cdn.shopify.com/shopifycloud/polaris-2.js' }],
  ],

  // Per-page tags that need the page's own title/description/URL: canonical,
  // Open Graph and Twitter. Site-wide static tags stay in `head` above.
  transformPageData(pageData, { siteConfig }) {
    const url = pageUrl(pageData.relativePath)
    const isHome = pageData.frontmatter.layout === 'home'
    const locale = localeOf(pageData.relativePath)
    const title = isHome
      ? `${pageData.title} | ${SITE_NAME}`
      : pageData.title === SITE_NAME
        ? SITE_NAME
        : `${pageData.title} | ${SITE_NAME}`
    const description = pageData.description || locale.siteDescription

    const head: HeadConfig[] = [
      ['link', { rel: 'canonical', href: url }],
      ['meta', { property: 'og:url', content: url }],
      ['meta', { property: 'og:title', content: title }],
      ['meta', { property: 'og:description', content: description }],
      ['meta', { name: 'twitter:title', content: title }],
      ['meta', { name: 'twitter:description', content: description }],
      ['meta', { property: 'og:locale', content: locale.ogLocale }],
    ]

    // hreflang alternates, only to translations that actually exist.
    const alternates = LOCALES.map((l) => ({ l, path: counterpart(pageData.relativePath, l) })).filter(
      ({ path }) => siteConfig.pages.includes(path),
    )
    if (alternates.length > 1) {
      for (const { l, path } of alternates) {
        head.push(['link', { rel: 'alternate', hreflang: l.hreflang, href: pageUrl(path) }])
      }
      head.push(['link', { rel: 'alternate', hreflang: 'x-default', href: pageUrl(counterpart(pageData.relativePath, LOCALES[0])) }])
    }

    // Site-level structured data belongs to the canonical (English) homepage only.
    if (isHome && locale.code === 'en') {
      // Google picks the site name shown above the URL in results from this.
      head.push([
        'script',
        { type: 'application/ld+json' },
        JSON.stringify({
          '@context': 'https://schema.org',
          '@type': 'WebSite',
          name: SITE_NAME,
          alternateName: 'Polaris Vue Elements',
          url: `${SITE_URL}/`,
        }),
      ])
      head.push([
        'script',
        { type: 'application/ld+json' },
        JSON.stringify({
          '@context': 'https://schema.org',
          '@type': 'SoftwareSourceCode',
          name: SITE_NAME,
          description: SITE_DESCRIPTION,
          url: SITE_URL,
          codeRepository: 'https://github.com/HQCuong/polaris-vue',
          programmingLanguage: ['TypeScript', 'Vue'],
          runtimePlatform: 'Vue 3',
          license: 'https://opensource.org/licenses/MIT',
          keywords: 'shopify, shopify app, shopify app home, polaris, web components, vue, vue 3, typescript',
        }),
      ])
    }

    pageData.frontmatter.head = [...(pageData.frontmatter.head ?? []), ...head]
  },

  vue: {
    template: {
      compilerOptions: {
        // Polaris web components (`<s-button>`, `<s-text-field>`, ...) are
        // custom elements, not Vue components — don't warn/resolve them as such.
        isCustomElement: (tag) => tag.startsWith('s-'),
      },
    },
  },

  vite: {
    resolve: {
      alias: {
        // Lets docs pages `import { SButton } from '@lib'` directly from source.
        '@lib': fileURLToPath(new URL('../../src/lib', import.meta.url)),
      },
    },
  },

  locales: localeConfigs(),

  themeConfig: {
    // https://vitepress.dev/reference/default-theme-config
    nav: [
      { text: 'Guide', link: '/guide/getting-started' },
      { text: 'Components', link: '/components/' },
    ],

    sidebar: [
      {
        text: 'Guide',
        items: [
          { text: 'Getting started', link: '/guide/getting-started' },
          { text: 'Build a Shopify embedded app', link: '/guide/shopify-embedded-app' },
          { text: 'Known quirks & gotchas', link: '/guide/quirks' },
          { text: 'All components', link: '/components/' },
        ],
      },
      // Spread rather than nested under a single "Components" parent: one more
      // level of nesting would push every component three deep and force two
      // clicks to reach any page.
      ...componentsSidebar,
    ],

    // Built-in MiniSearch index, built at build time from the full rendered text
    // of every page — so prop names, event names and prose are all searchable, not
    // just component titles. No external service, no runtime network call.
    search: {
      provider: 'local',
      options: {
        detailedView: true,
        locales: searchLocales(),
      },
    },

    outline: [2, 3],

    footer: {
      message:
        'Released under the MIT License. Vue logo by <a href="https://github.com/vuejs/art">Evan You</a>, CC BY-NC-SA 4.0.',
      copyright: 'Wrappers around Shopify Polaris web components — not affiliated with Shopify.',
    },

    socialLinks: [{ icon: 'github', link: 'https://github.com/HQCuong/polaris-vue' }],
  },
})
